/**
 * Test Utilities
 *
 * Provides custom render functions and utilities for component testing.
 * Wraps components with necessary providers (Auth, etc.) and provides
 * common testing helpers.
 *
 * Usage:
 *   import { render, screen } from '@/__tests__/utils/test-utils'
 *
 *   test('renders component', () => {
 *     render(<MyComponent />)
 *     expect(screen.getByText('Hello')).toBeInTheDocument()
 *   })
 */

import { ReactElement, ReactNode } from 'react'
import { render as rtlRender, RenderOptions } from '@testing-library/react'
import { AuthContext, AuthContextValue } from '@/components/providers/auth-provider'
import type { User, Session } from '@supabase/supabase-js'
import type { Organization, OrganizationMember, UserRole } from '@/types'

/**
 * Default mock user for tests
 */
export const mockUser: User = {
  id: 'test-user-id',
  email: 'test@example.com',
  aud: 'authenticated',
  role: 'authenticated',
  created_at: '2024-01-01T00:00:00Z',
  app_metadata: {},
  user_metadata: {},
  updated_at: '2024-01-01T00:00:00Z',
}

/**
 * Default mock session for tests
 */
export const mockSession: Session = {
  access_token: 'mock-access-token',
  refresh_token: 'mock-refresh-token',
  expires_in: 3600,
  expires_at: Math.floor(Date.now() / 1000) + 3600,
  token_type: 'bearer',
  user: mockUser,
}

/**
 * Default mock organization for tests
 */
export const mockOrganization: Organization = {
  id: 'test-org-id',
  name: 'Test Restaurant',
  slug: 'test-restaurant',
  is_active: true,
  created_at: '2024-01-01T00:00:00Z',
  updated_at: '2024-01-01T00:00:00Z',
}

/**
 * Default mock organization member for tests
 */
export const mockMembership: OrganizationMember = {
  id: 'test-membership-id',
  organization_id: 'test-org-id',
  user_id: 'test-user-id',
  role: 'owner' as UserRole,
  created_at: '2024-01-01T00:00:00Z',
  updated_at: '2024-01-01T00:00:00Z',
}

/**
 * Options for customizing the test render
 */
export interface CustomRenderOptions extends Omit<RenderOptions, 'wrapper'> {
  /** Custom auth context value */
  authContext?: Partial<AuthContextValue>
  /** Whether the user is authenticated (default: true) */
  isAuthenticated?: boolean
  /** Whether auth is loading (default: false) */
  isLoading?: boolean
}

/**
 * Create a mock auth context value with optional overrides
 */
export function createMockAuthContext(
  overrides: Partial<AuthContextValue> = {}
): AuthContextValue {
  return {
    user: mockUser,
    session: mockSession,
    isLoading: false,
    membership: mockMembership,
    organization: mockOrganization,
    role: 'owner',
    signOut: async () => {},
    refreshAuth: async () => {},
    setCurrentOrganization: async () => {},
    ...overrides,
  }
}

/**
 * Create an unauthenticated mock auth context
 */
export function createUnauthenticatedAuthContext(): AuthContextValue {
  return {
    user: null,
    session: null,
    isLoading: false,
    membership: null,
    organization: null,
    role: null,
    signOut: async () => {},
    refreshAuth: async () => {},
    setCurrentOrganization: async () => {},
  }
}

/**
 * Wrapper component that provides all necessary context for testing
 */
function TestWrapper({
  children,
  authContext,
}: {
  children: ReactNode
  authContext: AuthContextValue
}) {
  return <AuthContext.Provider value={authContext}>{children}</AuthContext.Provider>
}

/**
 * Custom render function that wraps components with test providers
 *
 * @param ui - The component to render
 * @param options - Render options including auth context overrides
 * @returns The render result from React Testing Library
 *
 * @example
 * // Render with default authenticated user
 * render(<ProductList />)
 *
 * @example
 * // Render with custom user role
 * render(<ProductList />, {
 *   authContext: { role: 'staff' }
 * })
 *
 * @example
 * // Render as unauthenticated
 * render(<LoginPage />, {
 *   isAuthenticated: false
 * })
 */
export function render(
  ui: ReactElement,
  {
    authContext = {},
    isAuthenticated = true,
    isLoading = false,
    ...renderOptions
  }: CustomRenderOptions = {}
) {
  // Create the auth context based on authentication state
  const authContextValue = isAuthenticated
    ? createMockAuthContext({ isLoading, ...authContext })
    : createUnauthenticatedAuthContext()

  // Render with wrapper
  const wrapper = ({ children }: { children: ReactNode }) => (
    <TestWrapper authContext={authContextValue}>{children}</TestWrapper>
  )

  return rtlRender(ui, { wrapper, ...renderOptions })
}

/**
 * Wait for a condition to be true with a timeout
 *
 * @param condition - Function that returns true when condition is met
 * @param timeout - Maximum time to wait in milliseconds (default: 5000)
 * @throws Error if condition is not met within timeout
 */
export async function waitFor(condition: () => boolean, timeout = 5000): Promise<void> {
  const startTime = Date.now()
  while (!condition()) {
    if (Date.now() - startTime > timeout) {
      throw new Error('Condition not met within timeout')
    }
    await new Promise((resolve) => setTimeout(resolve, 50))
  }
}

/**
 * Wait for an async condition to be true with a timeout
 *
 * @param condition - Async function that returns true when condition is met
 * @param timeout - Maximum time to wait in milliseconds (default: 5000)
 * @throws Error if condition is not met within timeout
 */
export async function waitForAsync(
  condition: () => Promise<boolean>,
  timeout = 5000
): Promise<void> {
  const startTime = Date.now()
  while (!(await condition())) {
    if (Date.now() - startTime > timeout) {
      throw new Error('Condition not met within timeout')
    }
    await new Promise((resolve) => setTimeout(resolve, 50))
  }
}

// Re-export everything from React Testing Library
export * from '@testing-library/react'

// Export userEvent as a named export for convenience
export { default as userEvent } from '@testing-library/user-event'
